export type Job<T> = () => Promise<T> | T;

export class JobQueue {
  private readonly concurrency: number;
  private readonly maxRetries: number;
  private readonly pending: Array<() => void> = [];
  private idleWaiters: Array<() => void> = [];
  private active = 0;

  constructor(concurrency: number, maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    if (!Number.isInteger(maxRetries) || maxRetries < 0) {
      throw new RangeError("maxRetries must be a non-negative integer");
    }
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
  }

  /** Number of jobs waiting or running. */
  get size(): number {
    return this.pending.length + this.active;
  }

  /**
   * Enqueues a job. The returned promise settles with the job's result, or
   * rejects with its last error once all retries are exhausted.
   */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.runWithRetries(job));
        } catch (err) {
          reject(err);
        }
        this.active--;
        this.drain();
      });
      this.drain();
    });
  }

  /** Resolves once no jobs are waiting or running. Never rejects. */
  onIdle(): Promise<void> {
    if (this.size === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.maxRetries) throw err;
      }
    }
  }

  private drain(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      this.active++;
      this.pending.shift()!();
    }
    if (this.size === 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { JobQueue } from "./jobQueue.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

test("respects the concurrency limit", async () => {
  const queue = new JobQueue(2);
  let running = 0;
  let peak = 0;
  for (let i = 0; i < 10; i++) {
    queue.add(async () => {
      peak = Math.max(peak, ++running);
      await sleep(5);
      running--;
    });
  }
  await queue.onIdle();
  assert.equal(peak, 2);
  assert.equal(queue.size, 0);
});

test("retries a failing job up to three times, then rejects", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const result = queue.add(async () => {
    calls++;
    throw new Error("boom");
  });
  await assert.rejects(result, /boom/);
  assert.equal(calls, 4);
});

test("resolves when a retry succeeds", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const value = await queue.add(() => {
    if (++calls < 3) throw new Error("flaky");
    return "ok";
  });
  assert.equal(value, "ok");
  assert.equal(calls, 3);
});

test("onIdle waits for failed jobs and jobs added while running", async () => {
  const queue = new JobQueue(2);
  const done: string[] = [];
  queue.add(async () => {
    await sleep(5);
    queue.add(async () => {
      await sleep(5);
      done.push("nested");
    });
    done.push("outer");
  });
  queue.add(() => Promise.reject(new Error("x"))).catch(() => done.push("failed"));
  await queue.onIdle();
  assert.deepEqual(done.sort(), ["failed", "nested", "outer"]);
  await queue.onIdle(); // already idle: resolves immediately
});

